export interface PartsStore {
  shortfall(partNo: string, units: number, jobId: string): number;
}

PartsStore.prototype.shortfall = function (
  this: PartsStore,
  partNo: string,
  units: number,
  jobId: string
): number {
  let reach: number;
  try {
    reach = this.freeOf(partNo) + this.heldFor(partNo, jobId);
  } catch {
    return units;
  }
  if (!Number.isFinite(reach)) return units;
  return Math.max(0, units - reach);
};
